 slang=("Daichi",["💼","#AE3EC9"],["F: うわ、めっちゃ疲れてるじゃん。 | Nossa, você está exausto. | uwa, meccha tsukareteru jan.","Y: 昨日、徹夜しちゃってさ。 | Virei a noite ontem. | kinō, tetsuya shichatte sa.","F: ちょっと休んだら？ コーヒーおごるよ。 | Que tal descansar um pouco? Eu pago o café. | chotto yasundara? kōhī ogoru yo.","Y: マジで？ 神！ | Sério? Divino! | maji de? kami!","F: そのかわり、あとで手伝ってね。 | Em troca, me ajude depois. | sono kawari, ato de tetsudatte ne.","Y: もちろん！ | Claro! | mochiron!"],
  {"徹夜":"virar a noite","おごる":"pagar para alguém","じゃん":"não é? (casual)","神":"incrível, divino (gíria)","そのかわり":"em troca"},["徹夜","おごる"]),
